using System.Windows;using AutoPecasERP.Core.Entities;using AutoPecasERP.Data.Context;using AutoPecasERP.Services.Financeiro;using Microsoft.EntityFrameworkCore;
namespace AutoPecasERP.Desktop.Views;
public partial class FinanceiroWindow:Window{readonly Usuario _u;readonly ErpDbContext _db=new();FinanceiroService S=>new(_db);public FinanceiroWindow(Usuario u){InitializeComponent();_u=u;Loaded+=async(_,__)=>await Atualizar();}
async Task Atualizar(){var c=await S.CaixaAbertoAsync();StatusCaixa.Text=c==null?"CAIXA FECHADO":$"CAIXA ABERTO • {c.Abertura:g}";ReceberGrid.ItemsSource=await _db.ContasReceber.OrderByDescending(x=>x.Id).ToListAsync();MovGrid.ItemsSource=c?.Movimentos.OrderByDescending(x=>x.Data).ToList();}
async void Abrir_Click(object s,RoutedEventArgs e){var d=new ValorDialog("Abertura de caixa"){Owner=this};if(d.ShowDialog()!=true)return;try{await S.AbrirCaixaAsync(d.Valor,_u.Nome);await Atualizar();}catch(Exception ex){MessageBox.Show(ex.Message);}}
async void Suprimento_Click(object s,RoutedEventArgs e){var d=new ValorDialog("Suprimento"){Owner=this};if(d.ShowDialog()!=true)return;try{await S.MovimentarAsync("SUPRIMENTO",d.Valor,string.IsNullOrWhiteSpace(d.Observacao)?"Suprimento":d.Observacao,_u.Nome);await Atualizar();}catch(Exception ex){MessageBox.Show(ex.Message);}}
async void Sangria_Click(object s,RoutedEventArgs e){var d=new ValorDialog("Sangria"){Owner=this};if(d.ShowDialog()!=true)return;try{await S.MovimentarAsync("SANGRIA",d.Valor,string.IsNullOrWhiteSpace(d.Observacao)?"Sangria":d.Observacao,_u.Nome);await Atualizar();}catch(Exception ex){MessageBox.Show(ex.Message);}}
async void Fechar_Click(object s,RoutedEventArgs e){var d=new ValorDialog("Fechamento - saldo contado"){Owner=this};if(d.ShowDialog()!=true)return;try{var c=await S.FecharAsync(d.Valor,_u.Nome);var dif=c.SaldoFinalInformado-c.SaldoCalculado;MessageBox.Show($"Caixa fechado.\nCalculado: {c.SaldoCalculado:C}\nInformado: {c.SaldoFinalInformado:C}\nDiferença: {dif:C}");await Atualizar();}catch(Exception ex){MessageBox.Show(ex.Message);}}
async void Receber_DoubleClick(object s,System.Windows.Input.MouseButtonEventArgs e){if(ReceberGrid.SelectedItem is not ContaReceber t)return;try{await S.BaixarReceberAsync(t.Id,t.Valor,t.FormaPagamento,_u.Nome);await Atualizar();}catch(Exception ex){MessageBox.Show(ex.Message);}}}